//! Genuine source-only collector failures cannot become a completed custom report.
#[path="../fixtures/native-doc-snippets-workspace/fixture.rs"]mod fixture;
use crate::{captured_raw_tree_pages::Policy,captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io,cell::Cell};
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,phase:Cell<usize>,stop:Option<usize>,error:Option<usize>}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{let phase=self.phase.get()+1;self.phase.set(phase);if self.error==Some(phase){return Err(Failure::Operational(io::Error::from_raw_os_error(1450)))}if self.stop==Some(phase){return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
fn pages<'a>(root:&'a Path,b:&Arc<Budget>)->Pages<'a>{let rows=fixture::files(0).into_iter().filter(|(p,_)|Policy::DocSnippets.selects_path(p)).map(|(p,s)|{let source=dm_preprocess::AcquiredSource::from_original_bytes(s.into_bytes(),());(p.into(),source.lease().source_text().clone())}).collect();Pages{root,rows,budget:Arc::clone(b),phase:Cell::new(0),stop:None,error:None}}
#[test]fn doc_snippets_three_actual_source_phases_refuse_incomplete_or_io_and_recover(){let root=std::env::current_dir().unwrap().join("doc-custody-root");let b=Budget::new(256*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::ProvenMissing).unwrap();for phase in 1..=3{let mut input=pages(&root,&b);input.stop=Some(phase);assert!(matches!(crate::captured_raw_tree_pages::collect(&input,Policy::DocSnippets,&config,&b,&||Ok(())),Err(Failure::Unsupported(s))if s.contains("EOF")));assert_eq!(input.phase.get(),phase);let mut input=pages(&root,&b);input.error=Some(phase);assert!(matches!(crate::captured_raw_tree_pages::collect(&input,Policy::DocSnippets,&config,&b,&||Ok(())),Err(Failure::Operational(e))if e.raw_os_error()==Some(1450)));assert_eq!(input.phase.get(),phase);}let input=pages(&root,&b);let output=crate::captured_raw_tree_pages::collect(&input,Policy::DocSnippets,&config,&b,&||Ok(())).unwrap();assert_eq!(input.phase.get(),3);assert!(!output.sites().is_empty());assert!(!output.doc_blocks().unwrap().is_empty());assert!(output.allow_used().iter().any(|u|u.name=="doc_snippets"));assert!(!output.sites().iter().any(|s|s.rel.contains("archive")||s.rel.contains(".hidden")));}
#[test]fn doc_snippets_quota_and_cancel_are_operational_not_unavailable_or_completed(){let root=std::env::current_dir().unwrap().join("doc-fail-root");let b=Budget::new(256*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::ProvenMissing).unwrap();let input=pages(&root,&b);let count=Cell::new(0);let poll=||{let n=count.get()+1;count.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};assert!(matches!(crate::captured_raw_tree_pages::collect(&input,Policy::DocSnippets,&config,&b,&poll),Err(Failure::Operational(e))if e.raw_os_error()==Some(1450)));assert_eq!(count.get(),32);let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let input=pages(&root,&denied);assert!(matches!(crate::captured_raw_tree_pages::collect(&input,Policy::DocSnippets,&config,&denied,&||Ok(())),Err(Failure::Operational(e))if e.kind()==io::ErrorKind::OutOfMemory));assert!(denied.denied());assert_eq!(Policy::DocSnippets.source_visits(),3);assert!(matches!(Policy::DocSnippets.metadata().policy,crate::lint::Policy::Custom));assert!(!crate::captured_raw_policy::RAW_FILE_LINTS.contains(&"doc_snippets"));}
